// ============================================================================
// UART_apb: APB4 register wrapper around UART_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/UART.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/UART.md
// ============================================================================
module UART_apb #(
  parameter int CLK_FREQ = 50_000_000,
  parameter int BAUD = 115_200
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic rxd,
  output logic txd
);
  localparam logic [31:0] ID_VALUE = 32'h55410200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [6:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd7) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic [7:0]    c_tx_data;
  logic          c_tx_valid;
  logic          c_tx_ready;
  logic [7:0]    c_rx_data;
  logic          c_rx_valid;
  logic          c_irq;
  UART_top #(.CLK_FREQ(CLK_FREQ), .BAUD(BAUD)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .rxd(rxd),
    .txd(txd),
    .tx_data(c_tx_data),
    .tx_valid(c_tx_valid),
    .tx_ready(c_tx_ready),
    .rx_data(c_rx_data),
    .rx_valid(c_rx_valid),
    .irq(c_irq)
  );

  // ---------------- registers ----------------
  logic [4:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [7:0] h_TXDATA;   // 12'h014 TXDATA holding register
  logic [7:0] h_RXDATA;   // 12'h018 RXDATA holding register
  logic full_TXDATA;
  logic avail_RXDATA;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      h_TXDATA <= '0;
      h_RXDATA <= '0;
      full_TXDATA <= 1'b0;
      avail_RXDATA <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[4:0] & wmask[4:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[4:0]) | (PWDATA[4:0] & wmask[4:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5] && !full_TXDATA) h_TXDATA <= (h_TXDATA & ~wmask[7:0]) | (PWDATA[7:0] & wmask[7:0]);
      if (wr && hit[5] && !full_TXDATA) full_TXDATA <= 1'b1;
      else if (full_TXDATA && c_tx_ready) full_TXDATA <= 1'b0;
      if (c_rx_valid && (!avail_RXDATA || (rd && hit[6]))) begin
        h_RXDATA[7:0] <= c_rx_data[7:0];
        avail_RXDATA <= 1'b1;
      end else if (rd && hit[6]) avail_RXDATA <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_tx_data[7:0] = h_TXDATA[7:0];
  assign c_tx_valid = full_TXDATA;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_irq;
    irq_set[1] = full_TXDATA & c_tx_ready;
    irq_set[2] = wr & (hit[5]) & full_TXDATA;
    irq_set[3] = c_rx_valid & (~avail_RXDATA | (rd & hit[6]));
    irq_set[4] = c_rx_valid & avail_RXDATA & ~(rd & hit[6]);
  end
  assign irq = |(irq_status & irq_enable);
  wire [1:0] flags = {avail_RXDATA, full_TXDATA};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(h_TXDATA);
      10'd6: apb_rdata = 32'(h_RXDATA);
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
